        tablePropsToAdd.put(HoodieTableConfig.RECORD_MERGE_STRATEGY_ID, HoodieRecordMerger.EVENT_TIME_BASED_MERGE_STRATEGY_UUID);
      } else {
        setEventTimeOrCommitTimeBasedOnPayload(payloadClass, tablePropsToAdd);
      }
    }
}
